<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<block v-else>
		<view class="top">
			<view class="head">
				<image :src="user.head_pic" mode="scaleToFill" class="head-img"/>
				<text>{{user.nickname}}</text>
				<text class="level" v-if="user.is_open==1">{{user.level_text}}</text>
			</view>
			<view class="bottom">
				<view class="bottom-info">
					<image src="@/static/my/zs-level.png" mode="widthFix" class="zs-img" />
					<text v-if="user.is_open==0">您还没有开通会员~</text>
					<text v-else>到期时间：{{user.end_time}}</text>
				</view>
				<image src="@/static/my/user-center-right.png" mode="heightFix" class="center-img" />
			</view>
		</view>
		<view class="info" v-if="user.is_open==0">
			<view class="info-title">
				<image src="@/static/my/center-title.png" mode="widthFix" class="title-img" />
				<text>开通会员</text>
				<image src="@/static/my/center-title.png" mode="widthFix" class="title-img" />
			</view>
			<view class="info-desc">购买以下商品即可加入会员<br>购买后不支持退款！</view>
			<view class="goods">
				<image :src="goods.goods_img" mode="scaleToFill" class="goods-img"/>
				<view class="right">
					<view class="goods-name">{{goods.goods_name}}</view>
					<view class="bot">
						<text class="fuhao">¥</text>
						<text class="jiage">{{goods.goods_price}}</text>
					</view>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="openNow"
					:disabled="submitDisabled">立即开通</button>
			</view>
		</view>
		<view class="info info-open" v-else>
			<view class="title">积分</view>
			<view class="jf-inner">
				<text class="money">{{user.sum_jifen}}</text>
				<view class="hint">
					<u-icon name="info-circle" color="#959595" size="18"/>
					<text>已领取{{user.already_jifen}}积分 每日可领取{{user.day_jifen}}积分</text>
				</view>
			</view>
			<view class="title">视频专区</view>
			<view class="tishi">看视频享积分赠送，快来试试吧！</view>
			<view class="ad">
				
			</view>
		</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				submitDisabled:false,
				user:{},
				goods:{},
			}
		},
		onLoad(e) {
			_this = this;
		},
		onShow() {
			_this.get_my_center()
		},
		methods: {
			async get_my_center(){
				const data = await _this.$post('port/my_center')
				if (data.code == 200) {
					_this.user = data.result.user
					_this.goods = data.result.goods
					if (_this.load) {
						_this.load = false
					}
				} else if(data.code == -50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else {
					uni.$u.toast(data.msg)
				}
			},
			openNow(){
				_this.toNext(`/pages/index/goods-detail?goods_id=${_this.goods.goods_id}`)
			}
		}
	}
</script>

